async function safe<T>(p: Promise<T>): Promise<T | string> { try { return await p; } catch (e) { return "ERR: " + (e as Error).message; } }
const [g1, g2, g3] = await Promise.all([
  safe(tools.grep({ pattern: "def topologicalClosure|theorem.*topologicalClosure|lemma.*topologicalClosure|namespace.*topologicalClosure", include: "*.lean", path: ".lake/packages/mathlib/Mathlib/Topology/Algebra" })),
  safe(tools.grep({ pattern: "topologicalClosure", include: "*.lean", path: ".lake/packages/mathlib/Mathlib/Topology/Algebra/OpenSubgroup.lean" })),
  safe(tools.grep({ pattern: "topologicalClosure_finiteIndex|finiteIndex.*topologicalClosure|topologicalClosure.*FiniteIndex", include: "*.lean", path: ".lake/packages/mathlib/Mathlib" })),
]);
for (const [n,g] of [["topologicalClosure defs",g1],["OpenSubgroup",g2],["finiteIndex closure",g3]] as const) {
  console.log("=====", n, typeof g === "string" ? g : (g as any).matches.length);
  if (typeof g !== "string") for (const m of (g as any).matches.slice(0,40)) console.log(m.path.split("\\").slice(-3).join("/")+":"+m.lineNumber+":"+m.line.slice(0,200));
}
", "description": "Check Subgroup.topologicalClosure API"}

